  "timing.intervalHint.minute": "\u041D\u0435 \u043C\u0435\u043D\u0435\u0435 1 \u043C\u0438\u043D\u0443\u0442\u044B. \u041F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043E\u043A \u043E\u0442\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0442 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u044F \u0437\u0430\u0434\u0430\u0447\u0438 \u0438\u043B\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043F\u0440\u0430\u0432\u043A\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u0438 \u043D\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0433\u043E \u043F\u043E\u044F\u0441\u0430.",
  "timing.intervalHint.second": "\u041D\u0435 \u043C\u0435\u043D\u0435\u0435 60 \u0441\u0435\u043A\u0443\u043D\u0434. \u041F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043E\u043A \u043E\u0442\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0442 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u044F \u0437\u0430\u0434\u0430\u0447\u0438 \u0438\u043B\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043F\u0440\u0430\u0432\u043A\u0438 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u0438 \u043D\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0447\u0430\u0441\u043E\u0432\u043E\u0433\u043E \u043F\u043E\u044F\u0441\u0430.",
  "timing.zoneNoStored": "\u0420\u0430\u0437\u043E\u0432\u0430\u044F \u0437\u0430\u0434\u0430\u0447\u0430 \u0445\u0440\u0430\u043D\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043C\u043E\u043C\u0435\u043D\u0442 \u0437\u0430\u043F\u0443\u0441\u043A\u0430, \u0430 \u043D\u0435 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u043F\u043E\u044F\u0441. \u0414\u0430\u0442\u0430 \u0438 \u0432\u0440\u0435\u043C\u044F \u043F\u043E\u043D\u0438\u043C\u0430\u044E\u0442\u0441\u044F \u0432 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u043C \u043F\u043E\u044F\u0441\u0435.",
